const body = $input.first().json.body || $input.first().json;
const eventType = body.type || 'MESSAGE';

// Case 1: User submitted the form via Card/Dialog click
if (eventType === 'CARD_CLICKED') {
  const formInputs = body.common?.formInputs || {};
  const title = formInputs.task_title?.stringInputs?.value?.[0] || 'New Task from Google Chat';
  const priority = formInputs.priority?.stringInputs?.value?.[0] || 'P2 - High';
  const complexity = formInputs.complexity?.stringInputs?.value?.[0] || '⭐ 3 - Moderate';
  const dueDate = formInputs.due_date?.stringInputs?.value?.[0] || new Date().toISOString().split('T')[0];
  const notes = formInputs.notes?.stringInputs?.value?.[0] || 'Created via Google Chat interactive bot.';
  const sender = body.user?.displayName || 'Google Chat User';

  return [{
    json: {
      action: 'create_task',
      title,
      priority,
      complexity,
      dueDate,
      notes,
      sender,
      spaceName: body.space?.name
    }
  }];
}

// Case 2: User sent a text message in Space (e.g. '@WASP task', 'create task', or '/task')
const rawText = body.message?.argumentText || body.message?.text || '';
const cleanText = rawText.replace(/@\S+/g, '').trim();
const senderName = body.user?.displayName || 'Team Member';

// If text includes task details directly, parse title
const taskTitleCandidate = cleanText.replace(/^(task|create|new|add)\s*/i, '').trim();

return [{
  json: {
    action: 'prompt_form',
    defaultTitle: taskTitleCandidate || 'New Deliverable',
    senderName,
    spaceName: body.space?.name
  }
}];

